function deleteProject(){
  if(!online){toast('로컬 모드 — Supabase 연결이 필요합니다');return;}
  var sel=document.getElementById('proj');var id=sel.value;
  if(!id){toast('삭제할 사업을 먼저 선택하세요');return;}
  var nm=(sel.options[sel.selectedIndex]&&sel.options[sel.selectedIndex].text)||'(이름없음)';
  if(!confirm("'"+nm+"' 사업을 삭제할까요?\n\n삭제목록에 7일간 보관되며 그 안에는 복원할 수 있습니다.\n7일이 지나면 사진까지 자동 완전삭제됩니다."))return;
  projSoftDelete(id,nm);
}
function deleteProjectById(id,nm,quiet){
  if(!online){toast('로컬 모드 — Supabase 연결이 필요합니다');return Promise.resolve();}
  // 사진 스토리지 정리(best-effort) → 사진행 → 이력 → 사업 순서
  return Promise.resolve()
    .then(function(){return sb.storage.from('photos').list(id).then(function(r){
        var files=((r&&r.data)||[]).map(function(f){return id+'/'+f.name;});
        return files.length?sb.storage.from('photos').remove(files):null;
      }).catch(function(){});})
    .then(function(){return sb.from(DB+'_photos').delete().eq('project_id',id);})
    .then(function(){return sb.from(DB+'_history').delete().eq('project_id',id);})
    .then(function(){return sb.from(DB+'_projects').delete().eq('id',id);})
    .then(function(res){
      if(res&&res.error){toast('삭제 오류: '+res.error.message);return;}
      if(state.projectId===id){ // 현재 열려있던 사업이면 화면 초기화
        state.projectId=null;state.projectName=null;state.points=[];state.lines=[];state.baseTexts=[];state.markups=[];state.manholes=[];state.gpsPts=[];state.bpzones=[];state.roadZones=[];state.depthCheck=[];state.labelOff={};state.depthGround=null;state.finalCsv=[];state.photoDir={};state.bizInfo=null;state.routingDone=false;state.asbuilt=null;state.fieldDone=null;state.tangoDone=null;state.tgCarrier=null;state.mhDel=null;state.tgNotes=null;state._importSrc=[];photoMap={};afterMap={};selNum=null;
        clearSvg(gSel);clearSvg(gMH);if(typeof clearLabels==='function'){try{clearLabels('gps');}catch(e){}}redrawAll();updMeta();if(photoPanelOpen)refreshPhotoPanel();
      }
      if(!quiet){refreshProjects();toast('사업 완전삭제: '+(nm||''));}
    });
}

/* ====== [BUILD 1058] 사업 7일 휴지통 ====== */
function _projAlive(res){
  if(!res||!res.data)return res;
  return {data:res.data.filter(function(r){return !(r&&(r.del||(r.payload&&r.payload.delAt)));}),error:res.error};
}
function _projLeftDays(delAt){
  var d=7-Math.floor((Date.now()-(+delAt||0))/86400000);
  return d<0?0:d;
}
function projClearScreen(){
  state.projectId=null;state.projectName=null;state.points=[];state.lines=[];state.baseTexts=[];state.markups=[];state.manholes=[];state.gpsPts=[];state.bpzones=[];state.roadZones=[];state.depthCheck=[];state.labelOff={};state.depthGround=null;state.finalCsv=[];state.photoDir={};state.bizInfo=null;state.routingDone=false;state.asbuilt=null;state.fieldDone=null;state.tangoDone=null;state.tgCarrier=null;state.mhDel=null;state.tgNotes=null;state.mnList=[];state._importSrc=[];photoMap={};afterMap={};selNum=null;
  try{if(typeof mnCloseAll==='function')mnCloseAll();}catch(e){}
  try{if(typeof refReset==='function')refReset();}catch(e){}
  clearSvg(gSel);clearSvg(gMH);if(typeof clearLabels==='function'){try{clearLabels('gps');}catch(e){}}
  redrawAll();updMeta();if(photoPanelOpen)refreshPhotoPanel();
}
function projSoftDelete(id,nm){
  if(!online){toast('로컬 모드 — Supabase 연결이 필요합니다');return;}
  if(!id){toast('삭제할 사업을 먼저 선택하세요');return;}
  sb.from(DB+'_projects').select('payload').eq('id',id).single().then(function(r){
    if(r.error||!r.data){toast('삭제 오류: 사업을 찾을 수 없습니다');return;}
    var pl=r.data.payload||{};pl.delAt=Date.now();
    sb.from(DB+'_projects').update({payload:pl}).eq('id',id).then(function(res){
      if(res&&res.error){toast('삭제 오류: '+res.error.message);return;}
      if(state.projectId===id)projClearScreen();
      refreshProjects();
      toast('삭제목록으로 이동 — '+(nm||'')+' (7일 보관)');
    });
  });
}
function projRestore(id,nm){
  sb.from(DB+'_projects').select('payload').eq('id',id).single().then(function(r){
    if(r.error||!r.data){toast('복원 오류');return;}
    var pl=r.data.payload||{};delete pl.delAt;
    sb.from(DB+'_projects').update({payload:pl}).eq('id',id).then(function(res){
      if(res&&res.error){toast('복원 오류: '+res.error.message);return;}
      refreshProjects();projTrashFill();
      toast('복원됨: '+(nm||''));
    });
  });
}
function projHardDelete(id,nm){
  if(!confirm("'"+(nm||'')+"' 을(를) 완전히 삭제합니다.\n\n측점·결선·검수·사진이 모두 지워지며 되돌릴 수 없습니다."))return;
  toast('삭제 중…');
  deleteProjectById(id,nm,true).then(function(){refreshProjects();projTrashFill();toast('완전삭제됨: '+(nm||''));});
}
var _projPurged=false;
function projPurgeTrash(){
  if(!online||_projPurged)return;_projPurged=true;
  sb.from(DB+'_projects').select('id,name,payload').then(function(res){
    var lim=Date.now()-7*86400000;
    var old=(res.data||[]).filter(function(r){return r.payload&&r.payload.delAt&&(+r.payload.delAt)<lim;});
    if(!old.length)return;
    (function nx(){
      if(!old.length){refreshProjects();return;}
      var o=old.shift();
      try{deleteProjectById(o.id,o.name,true).then(nx,nx);}catch(e){nx();}
    })();
  });
}
function projTrashOpen(){
  if(!online){toast('로컬 모드 — Supabase 연결이 필요합니다');return;}
  var ex=document.getElementById('projTrashModal');if(ex)ex.remove();
  var wrap=document.createElement('div');wrap.id='projTrashModal';
  wrap.style.cssText='position:fixed;inset:0;background:rgba(22,28,38,.40);z-index:12000;display:flex;align-items:center;justify-content:center';
  wrap.onmousedown=function(e){if(e.target===wrap)wrap.remove();};
  var box=document.createElement('div');
  box.style.cssText='background:#fff;border-radius:12px;box-shadow:0 14px 44px rgba(0,0,0,.22);width:min(580px,93vw);max-height:78vh;display:flex;flex-direction:column;overflow:hidden';
  box.innerHTML='<div style="padding:13px 17px;border-bottom:1px solid #e9edf3;display:flex;align-items:center;gap:9px">'
   +'<span style="font-size:15px;font-weight:800;color:#33415a">\uD83D\uDDC2 \uC0AC\uC5C5 \uC0AD\uC81C\uBAA9\uB85D</span>'
   +'<span style="font-size:11.5px;color:#98a2b3">7\uC77C \uBCF4\uAD00 \uD6C4 \uC0AC\uC9C4\uAE4C\uC9C0 \uC790\uB3D9 \uC644\uC804\uC0AD\uC81C</span>'
   +'<button id="ptClose" style="margin-left:auto;background:#fff;border:1.5px solid #cfd8e3;color:#33415a;border-radius:8px;padding:5px 12px;font-size:12px;font-weight:700;cursor:pointer">\uB2EB\uAE30</button></div>'
   +'<div id="ptBody" style="padding:8px 14px 14px;overflow:auto;font-size:12.5px;color:#5b6577">\uBD88\uB7EC\uC624\uB294 \uC911\u2026</div>';
  wrap.appendChild(box);document.body.appendChild(wrap);
  document.getElementById('ptClose').onclick=function(){wrap.remove();};
  projTrashFill();
}
function projTrashFill(){
  var body=document.getElementById('ptBody');if(!body)return;
  sb.from(DB+'_projects').select('id,name,updated_at,del:payload->>delAt,stage:payload->>stage').then(function(res){/* [1421] */
    if(!document.getElementById('ptBody'))return;
    var rows=(res.data||[]).filter(function(r){return r.del&&((r.stage||'survey')===STAGE);});
    rows.sort(function(a,b){return (+b.del)-(+a.del);});
    if(!rows.length){body.innerHTML='<div style="padding:26px 6px;text-align:center;color:#98a2b3">\uC0AD\uC81C\uBAA9\uB85D\uC774 \uBE44\uC5B4\uC788\uC2B5\uB2C8\uB2E4</div>';return;}
    body.innerHTML=rows.map(function(r){
      var d=new Date(+r.del);/* [1421] */
      var ds=d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2)+'-'+('0'+d.getDate()).slice(-2);
      var left=_projLeftDays(r.del);
      var col=left<=2?'#d32f2f':'#8a94a6';
      return '<div style="display:flex;align-items:center;gap:8px;padding:9px 4px;border-bottom:1px solid #f0f3f7">'
        +'<div style="flex:1;min-width:0"><div style="font-weight:800;color:#33415a;font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+(r.name||'(\uC774\uB984\uC5C6\uC74C)')+'</div>'
        +'<div style="font-size:11px;color:'+col+';margin-top:2px">'+ds+' \uC0AD\uC81C \u00B7 '+left+'\uC77C \uB0A8\uC74C</div></div>'
        +'<button data-ptr="'+r.id+'" style="background:#f3f8f4;border:1.5px solid #b6ddc2;color:#1b7a3d;border-radius:8px;padding:5px 11px;font-size:12px;font-weight:700;cursor:pointer">\uBCF5\uC6D0</button>'
        +'<button data-ptd="'+r.id+'" style="background:#fff;border:1.5px solid #f0c4c4;color:#d32f2f;border-radius:8px;padding:5px 11px;font-size:12px;font-weight:700;cursor:pointer">\uC644\uC804\uC0AD\uC81C</button></div>';
    }).join('');
    var mp={};rows.forEach(function(r){mp[r.id]=r.name;});
    [].forEach.call(body.querySelectorAll('[data-ptr]'),function(b){b.onclick=function(){projRestore(b.getAttribute('data-ptr'),mp[b.getAttribute('data-ptr')]);};});
    [].forEach.call(body.querySelectorAll('[data-ptd]'),function(b){b.onclick=function(){projHardDelete(b.getAttribute('data-ptd'),mp[b.getAttribute('data-ptd')]);};});
  });
}
/* ---- 사업명 중복 확인 ---- */
function projDupCheck(name,cb){
  if(!online){cb(name);return;}
  sb.from(DB+'_projects').select('id,name,stage:payload->>stage').then(function(res){/* [1421] */
    var rows=(res.data||[]).filter(function(r){return r.id!==state.projectId&&((r.stage||'survey')===STAGE);});
    var names=rows.map(function(r){return r.name;});
    if(names.indexOf(name)<0){cb(name);return;}
    var dup=null;for(var k=0;k<rows.length;k++){if(rows[k].name===name){dup=rows[k];break;}}
    var trashed=!!(dup&&dup.payload&&dup.payload.delAt);
    var mk=function(n){var m=/^(.*)(_S)$/.exec(name);return m?(m[1]+'_'+n+m[2]):(name+'_'+n);};
    var i=1;while(names.indexOf(mk(i))>=0)i++;
    var cand=mk(i);
    var msg="'"+name+"' 사업명이 이미 있습니다."
      +(trashed?"\n(삭제목록에 보관 중인 사업입니다)":"")
      +"\n\n'"+cand+"' 으로 등록할까요?\n\n[취소] 을 누르면 사업명을 직접 고칠 수 있습니다.";
    if(!confirm(msg)){cb(null);return;}
    cb(cand);
  });
}


