      ws.pageSetup.margins={left:0.2,right:0.2,top:0.3,bottom:0.3,header:0.2,footer:0.2};
      ws.pageSetup.fitToPage=false;
      try{ws.pageSetup.printArea='A1:G'+ws.rowCount;}catch(_p2){}
