/* [1142] 표 그리기 공용 — 표시(canvas 직접)와 다운로드(rtBoardURL)가 같이 쓴다 */
function rtBoardTable(cx,W,H,pos,no){
  var pp=(typeof pointByNo==='function')?pointByNo(no):null;
  var name=(state.rtBoardName&&String(state.rtBoardName).trim())||rtShortName(state.projectName||'');   /* [1147] */
  var num=String(no).split('-').pop();
  var code=pp?String(pp.code||'').trim():'';
  var d6=String(no).slice(0,6);
  var date=/^\d{6}$/.test(d6)?('20'+d6.slice(0,2)+'.'+d6.slice(2,4)+'.'+d6.slice(4,6)):'';
  var rows=[['공사명',name],['번 호',num],['관 경',code],['날 짜',date]];
  var g=rtBoardGeom(W,H);
  var bw=g.bw, rh=g.rh, lw=g.lw;
  var x0=pos?Math.round(pos.fx*W):0;
  var y0=pos?Math.round(pos.fy*H):(H-rh*4);
  x0=Math.max(0,Math.min(W-bw,x0));y0=Math.max(0,Math.min(H-rh*4,y0));
  var pad=Math.round(rh*0.28);
  cx.fillStyle='#fff';cx.fillRect(x0,y0,bw,rh*4);
  cx.strokeStyle='#000';cx.lineWidth=Math.max(2,Math.round(H*0.0018));
  cx.textBaseline='middle';
  function fitText(s,maxW,baseF){
    var f=baseF;
    cx.font='700 '+f+'px sans-serif';
    while(f>8&&cx.measureText(s).width>maxW){f--;cx.font='700 '+f+'px sans-serif';}
  }
  var baseF=Math.round(rh*0.52);
  for(var i=0;i<4;i++){
    var yy=y0+rh*i;
    cx.strokeRect(x0,yy,lw,rh);
    cx.strokeRect(x0+lw,yy,bw-lw,rh);
    cx.fillStyle='#000';
    fitText(rows[i][0],lw-pad*2,baseF);
    cx.fillText(rows[i][0],x0+pad,yy+rh/2);
    fitText(rows[i][1],bw-lw-pad*2,baseF);
    cx.fillText(rows[i][1],x0+lw+pad,yy+rh/2);
  }
}
/* [BUILD2121] 지거 현황판 6행 — 사업명·번호·일자 자동 / 재질·관경·거리심도는 작업자 입력(설정 UI 차기, state.rtJgBoard9[지거번호]={mat,dia,ds} 예정) */
/* [BUILD2165] CSV 코드-지거 매칭 — 후측량·실시간 CSV의 코드 열 "N 지거"/"지거 N" 측점을 지거 N으로 인식 */
function jgCodeNum9(p){try{var c=String((p&&p.code)||'').trim();if(!c||c.indexOf('지거')<0)return null;var m=/(?:^|[^0-9])([0-9]+)\s*지거/.exec(' '+c)||/지거\s*([0-9]+)/.exec(c);return m?String(m[1]):null;}catch(_e){return null;}}
function jgFindDay9(n){try{var re=new RegExp('^([0-9]{6})-'+n+'-[1-4]$');var best=null;Object.keys((typeof photoMap!=='undefined'&&photoMap)||{}).forEach(function(k){var m=re.exec(k);if(m&&(!best||m[1]>best))best=m[1];});return best;}catch(_e){return null;}}
function rtJgBoardGeom9(W,H){var bw=Math.round(W*0.275),rh=Math.round(H*0.042);return {bw:bw,rh:rh,bh:rh*6,lw:Math.round(bw*0.34)};}
function rtJgBoardTable9(cx,W,H,pos,no){
  var name=(state.rtBoardName&&String(state.rtBoardName).trim())||rtShortName(state.projectName||'');
  var seg=String(no).split('-');var num=(seg.length>2)?seg[1]:(seg[1]||'');
  var d6=String(no).slice(0,6);
  var date=/^[0-9]{6}$/.test(d6)?('20'+d6.slice(0,2)+'.'+d6.slice(2,4)+'.'+d6.slice(4,6)):'';
  var jb=(state.rtJgBoard9&&state.rtJgBoard9[String(num)])||{};
  var rows=[['사업명',name],['번 호',num],['재 질',jb.mat||''],['관 경',jb.dia||''],['거리 / 심도',jb.ds||''],['일 자',date]];/* [BUILD2123] 순서 확정 */
  var g=rtJgBoardGeom9(W,H);
  var bw=g.bw, rh=g.rh, lw=g.lw, nR=6;
  var x0=pos?Math.round(pos.fx*W):0;
  var y0=pos?Math.round(pos.fy*H):(H-rh*nR);
  x0=Math.max(0,Math.min(W-bw,x0));y0=Math.max(0,Math.min(H-rh*nR,y0));
  var pad=Math.round(rh*0.28);
  cx.fillStyle='#fff';cx.fillRect(x0,y0,bw,rh*nR);
  cx.strokeStyle='#000';cx.lineWidth=Math.max(2,Math.round(H*0.0018));
  cx.textBaseline='middle';
  function fitText(t,maxW,baseF){var f=baseF;cx.font='700 '+f+'px sans-serif';while(f>8&&cx.measureText(t).width>maxW){f--;cx.font='700 '+f+'px sans-serif';}}
  var baseF=Math.round(rh*0.52);
  for(var i=0;i<nR;i++){
    var yy=y0+rh*i;
    cx.strokeRect(x0,yy,lw,rh);
    cx.strokeRect(x0+lw,yy,bw-lw,rh);
    cx.fillStyle='#000';
    fitText(rows[i][0],lw-pad*2,baseF);
    cx.fillText(rows[i][0],x0+pad,yy+rh/2);
    fitText(rows[i][1],bw-lw-pad*2,baseF);
    cx.fillText(rows[i][1],x0+lw+pad,yy+rh/2);
  }
}
