  var dset={};for(var _k2 in dm.dist)dset[_k2]=1;for(var _k3 in recs)dset[_k3]=1;
  (state.points||[]).forEach(function(p){var d0=p&&(p._d0||(''+p.no).split('-')[0]);if(d0&&/^[0-9]{6}$/.test(d0))dset[d0]=1;});
