function _pzOwnSet(s){var m=String(s||'').match(/\(([^)]*)\)/);var o={};if(m)String(m[1]).split(/[,+\/\u00b7;]/).forEach(function(t){t=refOwKey(t);if(t)o[t]=1;});return o;}/* [1550] \uc18c\uc720\uc790 \uc9d1\ud569 */
